arguments.command:
set -u
printf '%s\n' '== platform =='
uname -srm
printf 'arch='; uname -m
printf '%s\n' '== tools =='
for t in make gcc cc ocamlc ocamlopt ocamlfind opam coqc menhir perl python3; do
  if command -v "$t" >/dev/null 2>&1; then
    printf '%-10s %s\n' "$t" "$(command -v "$t")"
    case "$t" in
      ocamlc|ocamlopt) "$t" -version 2>/dev/null | head -n 1 ;;
      coqc) "$t" --version 2>/dev/null | head -n 2 ;;
      opam) "$t" --version 2>/dev/null | head -n 1 ;;
      make) "$t" --version 2>/dev/null | head -n 1 ;;
      gcc|cc) "$t" --version 2>/dev/null | head -n 1 ;;
      menhir) "$t" --version 2>/dev/null | head -n 1 ;;
    esac
  else
    printf '%-10s MISSING\n' "$t"
  fi
done

set -eux
cd /tmp/CompCert
printf '== executable ==\n'
test -x ./ccomp
ls -l ./ccomp
file ./ccomp
printf '\n== version ==\n'
./ccomp -version
printf '\n== configured target ==\n'
printf 'kernel: '; uname -s
printf 'machine: '; uname -m
sed -n -E '/^(ARCH|BITSIZE|SYSTEM|ENDIANNESS|ABI|CC|CLINKER_OPTIONS)=/p' Makefile.config
printf '\n== installed support ==\n'
test -f ./_install/share/compcert.ini
test -f ./_install/lib/compcert/libcompcert.a
test -f ./_install/lib/compcert/include/stdarg.h
ls -l ./_install/share/compcert.ini ./_install/lib/compcert/libcompcert.a

work=$(mktemp -d /tmp/compcert-smoke.XXXXXX)
trap 'rm -rf "$work"' EXIT
cat > "$work/smoke.c" <<'EOF'
#include <stdio.h>
#include <stdarg.h>

static long sum(int n, ...) {
  va_list ap;
  long total = 0;
  va_start(ap, n);
  for (int i = 0; i < n; i++) total += va_arg(ap, int);
  va_end(ap);
  return total;
}

int main(void) {
  volatile double x = 1.5;
  long total = sum(4, 3, 5, 7, 11);
  printf("sum=%ld scaled=%.1f\n", total, x * 4.0);
  return (total == 26 && x * 4.0 == 6.0) ? 0 : 1;
}
EOF
printf '\n== preprocess / assembly / object / linked executable ==\n'
./ccomp -E "$work/smoke.c" > "$work/smoke.i"
./ccomp -S "$work/smoke.c" -o "$work/smoke.s"
./ccomp -c "$work/smoke.c" -o "$work/smoke.o"
./ccomp "$work/smoke.c" -o "$work/smoke"
test -s "$work/smoke.i"
test -s "$work/smoke.s"
test -s "$work/smoke.o"
test -x "$work/smoke"
file "$work/smoke.o" "$work/smoke"
printf '\n== runtime result ==\n'
"$work/smoke"
printf '\n== exit status ==\n'
echo 0

